        public static void SubmitQualityEventToQA(int qualityEventId, string submittedBy)
        {
            ExecuteInTransaction((conn, tx) =>
            {
                EnsureQualityEventManagementAuthorizationInTransaction(
                    conn, tx, submittedBy, "submit a Quality Event to QA review");

                int affected = ExecuteNonQueryWithTransaction(@"
                    UPDATE dbo.QualityEvents
                    SET CurrentStatus = 'QA Review',
                        ModifiedBy = @submittedBy,
                        ModifiedDate = GETDATE()
                    WHERE QualityEventID = @qualityEventId
                      AND CurrentStatus NOT IN ('QA Review','Closed','QA Closed','Cancelled','Rejected Closed')",
                    new[]
                    {
                        new SqlParameter("@qualityEventId", qualityEventId),
                        new SqlParameter("@submittedBy", string.IsNullOrWhiteSpace(submittedBy) ? (object)DBNull.Value : submittedBy)
                    }, conn, tx);
                if (affected != 1)
                    throw new DBConcurrencyException("The Quality Event is already in QA Review or was changed by another user.");

                ExecuteNonQueryWithTransaction(@"
                    INSERT INTO dbo.QualityEventActions
                    (
                        QualityEventID,
                        ActionType,
                        ActionDescription,
                        PerformedBy,
                        PerformedDate
                    )
                    VALUES
                    (
                        @qualityEventId,
                        'Submit to QA',
                        'Investigation submitted to QA review.',
                        @submittedBy,
                        GETDATE()
                    )",
                    new[]
                    {
                        new SqlParameter("@qualityEventId", qualityEventId),
                        new SqlParameter("@submittedBy", string.IsNullOrWhiteSpace(submittedBy) ? (object)DBNull.Value : submittedBy)
                    }, conn, tx);

                AddAuditTrailAdvanced(
                    conn,
                    tx,
                    "QualityEvents",
                    qualityEventId,
                    "Submit Quality Event to QA",
                    "Open",
                    "QA Review",
                    "Investigation submitted to QA review",
                    submittedBy,
                    "CurrentStatus",
                    null,
                    null,
                    "Quality Event");
            });
        }

        public static void CloseQualityEvent(
            int qualityEventId,
            int sampleId,
            string qaConclusion,
            string finalDisposition,
            string closedBy,
            string signatureMeaning,
            string signatureReason,
            string userRole)
        {
            if (qualityEventId <= 0)
                throw new ArgumentOutOfRangeException(nameof(qualityEventId));
            if (string.IsNullOrWhiteSpace(qaConclusion))
                throw new InvalidOperationException("QA conclusion is required before Quality Event closure.");
            if (string.IsNullOrWhiteSpace(finalDisposition))
                throw new InvalidOperationException("Final disposition is required before Quality Event closure.");
            if (string.IsNullOrWhiteSpace(closedBy))
                throw new InvalidOperationException("An authenticated QA closer is required.");
            if (string.IsNullOrWhiteSpace(signatureMeaning))
                throw new InvalidOperationException("Electronic-signature meaning is required for Quality Event closure.");

            qaConclusion = qaConclusion.Trim();
            finalDisposition = finalDisposition.Trim();
            closedBy = closedBy.Trim();
            signatureMeaning = signatureMeaning.Trim();
            signatureReason = (signatureReason ?? string.Empty).Trim();

            ExecuteInTransaction((conn, tx) =>
            {
                string authorizedRole = EnsureQaClosureAuthorizationInTransaction(
                    conn, tx, closedBy, "close a Quality Event");
                userRole = authorizedRole;

                int? linkedSampleId = null;
                int? linkedEmEventId = null;
                string sourceRecordNumber = "";
                string eventNumber = "";
                string detectionSource = "";
                string sourceModule = "";
                string currentStatus = "";
                string severity = "";
                string initialDescription = "";
                string immediateAction = "";
                string rootCauseCategory = "";
                string rootCauseDetails = "";
                string impactAssessment = "";
                bool capaRequired = false;

                using (SqlCommand contextCommand = new SqlCommand(@"
                    SELECT TOP 1
                        QualityEventID,
                        SampleID,
                        SampleNumber,
                        EventNumber,
                        DetectionSource,
                        SourceModule,
                        CurrentStatus,
                        Severity,
                        InitialDescription,
                        ImmediateAction,
                        RootCauseCategory,
                        RootCauseDetails,
                        ImpactAssessment,
                        ISNULL(CAPARequired,0)
                    FROM dbo.QualityEvents WITH (UPDLOCK, HOLDLOCK)
                    WHERE QualityEventID = @qualityEventId;", conn, tx))
                {
                    contextCommand.CommandTimeout = AppConfig.CommandTimeoutSeconds;
                    contextCommand.Parameters.Add("@qualityEventId", SqlDbType.Int).Value = qualityEventId;

                    using (SqlDataReader reader = contextCommand.ExecuteReader())
                    {
                        if (!reader.Read())
                            throw new InvalidOperationException("The Quality Event record was not found.");

                        if (reader["SampleID"] != DBNull.Value)
                            linkedSampleId = Convert.ToInt32(reader["SampleID"], CultureInfo.InvariantCulture);

                        sourceRecordNumber = reader["SampleNumber"] == DBNull.Value
                            ? ""
                            : reader["SampleNumber"].ToString()?.Trim() ?? "";
                        eventNumber = reader["EventNumber"] == DBNull.Value
                            ? ""
                            : reader["EventNumber"].ToString()?.Trim() ?? "";
                        detectionSource = reader["DetectionSource"] == DBNull.Value
                            ? ""
                            : reader["DetectionSource"].ToString()?.Trim() ?? "";
                        sourceModule = reader["SourceModule"] == DBNull.Value ? "" : reader["SourceModule"].ToString()?.Trim() ?? "";
                        currentStatus = reader["CurrentStatus"] == DBNull.Value ? "" : reader["CurrentStatus"].ToString()?.Trim() ?? "";
                        severity = reader["Severity"] == DBNull.Value ? "" : reader["Severity"].ToString()?.Trim() ?? "";
                        initialDescription = reader["InitialDescription"] == DBNull.Value ? "" : reader["InitialDescription"].ToString()?.Trim() ?? "";
                        immediateAction = reader["ImmediateAction"] == DBNull.Value ? "" : reader["ImmediateAction"].ToString()?.Trim() ?? "";
                        rootCauseCategory = reader["RootCauseCategory"] == DBNull.Value ? "" : reader["RootCauseCategory"].ToString()?.Trim() ?? "";
                        rootCauseDetails = reader["RootCauseDetails"] == DBNull.Value ? "" : reader["RootCauseDetails"].ToString()?.Trim() ?? "";
                        impactAssessment = reader["ImpactAssessment"] == DBNull.Value ? "" : reader["ImpactAssessment"].ToString()?.Trim() ?? "";
                        capaRequired = !reader.IsDBNull(13) && reader.GetBoolean(13);
                    }
                }

                if (!currentStatus.Equals("QA Review", StringComparison.OrdinalIgnoreCase))
                    throw new DBConcurrencyException("The Quality Event is no longer in QA Review. Reload before closure.");
                if (string.IsNullOrWhiteSpace(severity))
                    throw new InvalidOperationException("Severity is required before Quality Event closure.");
                if (string.IsNullOrWhiteSpace(initialDescription))
                    throw new InvalidOperationException("Initial description is required before Quality Event closure.");
                if (string.IsNullOrWhiteSpace(immediateAction))
                    throw new InvalidOperationException("Immediate action is required before Quality Event closure.");
                if (string.IsNullOrWhiteSpace(rootCauseCategory) ||
                    rootCauseCategory.Equals("Pending Investigation", StringComparison.OrdinalIgnoreCase) ||
                    rootCauseCategory.Equals("Undetermined", StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException("A finalized root-cause category is required before Quality Event closure.");
                if (string.IsNullOrWhiteSpace(rootCauseDetails))
                    throw new InvalidOperationException("Root-cause details are required before Quality Event closure.");
                if (string.IsNullOrWhiteSpace(impactAssessment))
                    throw new InvalidOperationException("Impact assessment is required before Quality Event closure.");

                if (finalDisposition.Equals("Pending", StringComparison.OrdinalIgnoreCase) ||
                    finalDisposition.Equals("Retest Required", StringComparison.OrdinalIgnoreCase) ||
                    finalDisposition.Equals("Retest / Resample Required", StringComparison.OrdinalIgnoreCase) ||
                    finalDisposition.Equals("Retest Approved", StringComparison.OrdinalIgnoreCase) ||
                    finalDisposition.Equals("Resample Approved", StringComparison.OrdinalIgnoreCase) ||
                    finalDisposition.Equals("System Corrected / Monitoring Required", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Quality Event closure is blocked because the selected disposition still requires follow-up testing, resampling, monitoring, or investigation. Complete the follow-up evidence and select a final disposition.");
                }

                if (sourceModule.Equals("PRM", StringComparison.OrdinalIgnoreCase) &&
                    (finalDisposition.Equals("Accepted with Justification", StringComparison.OrdinalIgnoreCase) ||
                     finalDisposition.Equals("Released", StringComparison.OrdinalIgnoreCase) ||
                     finalDisposition.Equals("Rejected", StringComparison.OrdinalIgnoreCase) ||
                     finalDisposition.Equals("Batch/Material Hold", StringComparison.OrdinalIgnoreCase)))
                    throw new InvalidOperationException("PRM Quality Event closure requires an investigation outcome, not a batch/material release or rejection decision.");

                if (capaRequired)
                {
                    int capaEvidenceCount;
                    if (sourceModule.Equals("PRM", StringComparison.OrdinalIgnoreCase))
                    {
                        using SqlCommand prmCapaEvidence = new SqlCommand(@"
SELECT COUNT(1)
FROM dbo.QualityEventActions WITH (UPDLOCK,HOLDLOCK)
WHERE QualityEventID=@qualityEventId
  AND ActionType=N'PRM CAPA Action'
  AND NULLIF(LTRIM(RTRIM(ISNULL(ActionDescription,N''))),N'') IS NOT NULL;", conn, tx);
                        prmCapaEvidence.CommandTimeout = AppConfig.CommandTimeoutSeconds;
                        prmCapaEvidence.Parameters.Add("@qualityEventId", SqlDbType.Int).Value = qualityEventId;
                        capaEvidenceCount = Convert.ToInt32(prmCapaEvidence.ExecuteScalar(), CultureInfo.InvariantCulture);
                    }
                    else
                    {
                        using SqlCommand structuredCapaEvidence = new SqlCommand(@"
IF OBJECT_ID(N'dbo.QualityEventCAPAItems',N'U') IS NULL
   OR COL_LENGTH(N'dbo.QualityEventCAPAItems',N'QualityEventID') IS NULL
   OR COL_LENGTH(N'dbo.QualityEventCAPAItems',N'ActionDescription') IS NULL
   OR COL_LENGTH(N'dbo.QualityEventCAPAItems',N'ActionType') IS NULL
   OR COL_LENGTH(N'dbo.QualityEventCAPAItems',N'Responsible') IS NULL
BEGIN
    SELECT CONVERT(int,-1);
END
ELSE
BEGIN
    SELECT COUNT(1)
    FROM dbo.QualityEventCAPAItems WITH (UPDLOCK,HOLDLOCK)
    WHERE QualityEventID=@qualityEventId
      AND NULLIF(LTRIM(RTRIM(ISNULL(ActionDescription,N''))),N'') IS NOT NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(ActionType,N''))),N'') IS NOT NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(Responsible,N''))),N'') IS NOT NULL;
END;", conn, tx);
                        structuredCapaEvidence.CommandTimeout = AppConfig.CommandTimeoutSeconds;
                        structuredCapaEvidence.Parameters.Add("@qualityEventId", SqlDbType.Int).Value = qualityEventId;
                        capaEvidenceCount = Convert.ToInt32(structuredCapaEvidence.ExecuteScalar(), CultureInfo.InvariantCulture);
                        if (capaEvidenceCount < 0)
                            throw new InvalidOperationException("CAPA is required but the controlled structured CAPA schema is unavailable. Apply the approved database update before closure.");
                    }

                    if (capaEvidenceCount <= 0)
                        throw new InvalidOperationException(
                            sourceModule.Equals("PRM", StringComparison.OrdinalIgnoreCase)
                                ? "CAPA is required but no explicit PRM CAPA action has been documented."
                                : "CAPA is required but no complete structured CAPA action has been documented.");
                }

                if (linkedSampleId.HasValue && linkedSampleId.Value > 0)
                {
                    using (SqlCommand validateSampleCommand = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.Samples
                        WHERE SampleID = @sampleId;", conn, tx))
                    {
                        validateSampleCommand.CommandTimeout = AppConfig.CommandTimeoutSeconds;
                        validateSampleCommand.Parameters.Add("@sampleId", SqlDbType.Int).Value = linkedSampleId.Value;
                        int sampleCount = Convert.ToInt32(validateSampleCommand.ExecuteScalar(), CultureInfo.InvariantCulture);
                        if (sampleCount != 1)
                        {
                            throw new InvalidOperationException(
                                "The Quality Event references a laboratory sample that no longer exists. " +
                                "Closure was blocked to preserve referential integrity.");
                        }
                    }
                }
                else if (detectionSource.Equals("Environmental Monitoring", StringComparison.OrdinalIgnoreCase) ||
                         sourceRecordNumber.StartsWith("EM-", StringComparison.OrdinalIgnoreCase))
                {
                    using (SqlCommand resolveEmCommand = new SqlCommand(@"
                        IF OBJECT_ID(N'dbo.EM_Events', N'U') IS NULL
                            THROW 51330, 'Required table dbo.EM_Events is missing.', 1;

                        SELECT TOP 1 Id
                        FROM dbo.EM_Events
                        WHERE EventNo = @eventNo
                        ORDER BY Id DESC;", conn, tx))
                    {
                        resolveEmCommand.CommandTimeout = AppConfig.CommandTimeoutSeconds;
                        resolveEmCommand.Parameters.Add("@eventNo", SqlDbType.NVarChar, 50).Value = sourceRecordNumber;
                        object emId = resolveEmCommand.ExecuteScalar();
                        if (emId == null || emId == DBNull.Value)
                        {
                            throw new InvalidOperationException(
                                "The Environmental Monitoring event linked to this Quality Event could not be found. " +
                                "Closure was blocked to avoid writing a signature against the wrong record.");
                        }

                        linkedEmEventId = Convert.ToInt32(emId, CultureInfo.InvariantCulture);
                    }
                }
                else if (sampleId > 0)
                {
                    // Compatibility fallback for legacy Water events opened by SampleID before
                    // the QualityEvents.SampleID column was populated consistently.
                    using (SqlCommand validateLegacySampleCommand = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.Samples
                        WHERE SampleID = @sampleId;", conn, tx))
                    {
                        validateLegacySampleCommand.CommandTimeout = AppConfig.CommandTimeoutSeconds;
                        validateLegacySampleCommand.Parameters.Add("@sampleId", SqlDbType.Int).Value = sampleId;
                        int sampleCount = Convert.ToInt32(validateLegacySampleCommand.ExecuteScalar(), CultureInfo.InvariantCulture);
                        if (sampleCount == 1)
                            linkedSampleId = sampleId;
                    }
                }

                if (!linkedSampleId.HasValue && !linkedEmEventId.HasValue)
                {
                    throw new InvalidOperationException(
                        "The Quality Event source record could not be resolved to either dbo.Samples or dbo.EM_Events. " +
                        "Closure was blocked to preserve electronic-signature traceability.");
                }

                int affectedQualityEvents = ExecuteNonQueryWithTransaction(@"
                    UPDATE dbo.QualityEvents
                    SET CurrentStatus = 'Closed',
                        QAConclusion = @qaConclusion,
                        FinalDisposition = @finalDisposition,
                        ClosedBy = @closedBy,
                        ClosedDate = GETDATE(),
                        ModifiedBy = @closedBy,
                        ModifiedDate = GETDATE()
                    WHERE QualityEventID = @qualityEventId
                      AND CurrentStatus = 'QA Review'",
                    new[]
                    {
                        new SqlParameter("@qualityEventId", qualityEventId),
                        new SqlParameter("@qaConclusion", qaConclusion),
                        new SqlParameter("@finalDisposition", finalDisposition),
                        new SqlParameter("@closedBy", closedBy)
                    }, conn, tx);
                if (affectedQualityEvents != 1)
                    throw new DBConcurrencyException("The Quality Event was already changed or closed. Reload and retry.");

                ExecuteNonQueryWithTransaction(@"
                    INSERT INTO dbo.QualityEventActions
                    (
                        QualityEventID,
                        ActionType,
                        ActionDescription,
                        PerformedBy,
                        PerformedDate
                    )
                    VALUES
                    (
                        @qualityEventId,
                        'QA Closure',
                        'Quality Event closed by QA. Final disposition: ' + ISNULL(@finalDisposition, ''),
                        @closedBy,
                        GETDATE()
                    )",
                    new[]
                    {
                        new SqlParameter("@qualityEventId", qualityEventId),
                        new SqlParameter("@finalDisposition", string.IsNullOrWhiteSpace(finalDisposition) ? (object)DBNull.Value : finalDisposition),
                        new SqlParameter("@closedBy", string.IsNullOrWhiteSpace(closedBy) ? (object)DBNull.Value : closedBy)
                    }, conn, tx);

                if (linkedSampleId.HasValue)
                {
                    ExecuteNonQueryWithTransaction(@"
                        DECLARE @Ids TABLE(SignatureID INT NOT NULL);
                        INSERT dbo.ElectronicSignatures(SampleID,ActionType,ActionReason,SignedBy,SignedAt,MeaningOfSignature,UserRole)
                        OUTPUT INSERTED.SignatureID INTO @Ids(SignatureID)
                        VALUES(@sampleId,'Quality Event Closure',@signatureReason,@closedBy,GETDATE(),@signatureMeaning,@userRole);
                        INSERT dbo.QualityEventSignatures(QualityEventID,SignatureID,SignedBy,UserRole,MeaningOfSignature,SignedAt)
                        SELECT @qualityEventId,SignatureID,@closedBy,@userRole,@signatureMeaning,GETDATE() FROM @Ids;",
                        new[]
                        {
                            new SqlParameter("@qualityEventId", qualityEventId),
                            new SqlParameter("@sampleId", linkedSampleId.Value),
                            new SqlParameter("@signatureReason", string.IsNullOrWhiteSpace(signatureReason) ? (object)DBNull.Value : signatureReason),
                            new SqlParameter("@closedBy", closedBy),
                            new SqlParameter("@signatureMeaning", signatureMeaning),
                            new SqlParameter("@userRole", userRole)
                        }, conn, tx);
                }
                else
                {
                    string emSignatureReason = string.IsNullOrWhiteSpace(signatureReason)
                        ? "Quality Event " + eventNumber + " closure"
                        : "Quality Event " + eventNumber + " closure: " + signatureReason.Trim();

                    ExecuteNonQueryWithTransaction(@"
                        IF OBJECT_ID(N'dbo.EM_EventSignatures', N'U') IS NULL
                            THROW 51331, 'Required table dbo.EM_EventSignatures is missing.', 1;

                        INSERT INTO dbo.EM_EventSignatures
                        (
                            EventID,
                            EventNo,
                            ActionType,
                            ActionReason,
                            SignedBy,
                            UserRole,
                            MeaningOfSignature,
                            SignedAt
                        )
                        VALUES
                        (
                            @eventId,
                            @eventNo,
                            'Quality Event Closure',
                            @signatureReason,
                            @closedBy,
                            @userRole,
                            @signatureMeaning,
                            SYSDATETIME()
                        );",
                        new[]
                        {
                            new SqlParameter("@eventId", linkedEmEventId.Value),
                            new SqlParameter("@eventNo", string.IsNullOrWhiteSpace(sourceRecordNumber) ? (object)DBNull.Value : sourceRecordNumber),
                            new SqlParameter("@signatureReason", emSignatureReason),
                            new SqlParameter("@closedBy", closedBy),
                            new SqlParameter("@userRole", userRole),
                            new SqlParameter("@signatureMeaning", signatureMeaning)
                        }, conn, tx);
                }

                AddAuditTrailAdvanced(
                    conn,
                    tx,
                    "QualityEvents",
                    qualityEventId,
                    "Close Quality Event",
                    "QA Review",
                    "Closed",
                    signatureReason,
                    closedBy,
                    "CurrentStatus",
                    null,
                    null,
                    linkedEmEventId.HasValue ? "Quality Event / Environmental Monitoring" : "Quality Event");

                if (linkedSampleId.HasValue)
                {
                    string releaseStatus = "Released After Investigation";
                    if (string.Equals(finalDisposition, "Reject", StringComparison.OrdinalIgnoreCase))
                        releaseStatus = "Rejected";

                    ExecuteNonQueryWithTransaction(@"
                        UPDATE dbo.Samples
                        SET Status = @releaseStatus,
                            ModifiedBy = @closedBy,
                            ModifiedDate = GETDATE()
                        WHERE SampleID = @sampleId",
                        new[]
                        {
                            new SqlParameter("@sampleId", linkedSampleId.Value),
                            new SqlParameter("@releaseStatus", releaseStatus),
                            new SqlParameter("@closedBy", string.IsNullOrWhiteSpace(closedBy) ? (object)DBNull.Value : closedBy)
                        }, conn, tx);
                }
            });
        }

